/**
 * A side pane that shows one artifact a turn produced (`design/components/artifact-pane.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/artifact-pane.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  createKept,
  elementRef,
  resolveSlot,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/artifact-pane.module.css'
import Button from '../controls/Button'
import SegmentedControl from '../controls/SegmentedControl'
import Spinner from '../structure/Spinner'

export type ArtifactKind = 'code' | 'document' | 'data' | 'preview'

export interface ArtifactView {
  id: string
  label: string
  content: JSX.Element | string
}

export interface ArtifactPaneProps {
  /**
   * The header's controls (copy, download, open), as `ghost/neutral/sm` Buttons.
   */
  actions?: JSX.Element
  /**
   * The body when `views` is absent or empty. A non-empty `views` replaces it.
   */
  children?: JSX.Element
  /**
   * The close button's accessible name (generic default `Close`), which localized hosts replace.
   */
  closeLabel?: string
  defaultView?: string
  /**
   * The artifact's kind, which picks the mark (the tier's `artifact` glyph when absent).
   */
  kind?: 'code' | 'document' | 'data' | 'preview'
  /**
   * One preformatted line under the title, such as "TypeScript · 142 lines".
   */
  meta?: string
  /**
   * Shows the close button when supplied, and the app decides whether the pane stays mounted.
   */
  onClose?: () => void
  onViewChange?: (id: string) => void
  /**
   * Whether the artifact is still being written, which shows a spinner and sets `aria-busy`.
   */
  streaming?: boolean
  /**
   * The artifact's name, used as the pane's heading and accessible name.
   */
  title: string
  view?: string
  /**
   * The artifact's views (code, preview). Two or more draw a switch, and a single view is drawn
   * with no switch. When `views` is absent or empty, `children` is the body.
   */
  views?: ArtifactView[]
  /**
   * The switch's accessible name (generic default `View`).
   */
  viewsLabel?: string
}

/** A side pane that shows one artifact a turn produced. */
export default function ArtifactPane(given: ArtifactPaneProps): JSX.Element {
  const props = mergeProps(
    { streaming: false, closeLabel: 'Close', viewsLabel: 'View' } as Defaults<
      ArtifactPaneProps,
      'streaming' | 'closeLabel' | 'viewsLabel'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const viewsKept = createKept(() => props.views)
    const uid = createUniqueId()
    const body = elementRef<HTMLElement>()
    const closer = elementRef<HTMLElement>()
    const pane = elementRef<HTMLElement>()
    const switcher = elementRef<HTMLElement>()
    const actionsSlot = resolveSlot(() => props.actions)
    const overflowing = createCell(false)
    const mirror = createCell(props.defaultView ?? viewsKept.value?.[0]?.id)
    const titleId = createDerived(() => `${uid}-title`)
    const current = createDerived(() => props.view ?? mirror.value)
    const switching = createDerived(
      () => viewsKept.value !== undefined && viewsKept.value.length > 1,
    )
    const shown = createDerived(() =>
      viewsKept.value === undefined
        ? undefined
        : (viewsKept.value.find((entry) => entry.id === current.value) ?? viewsKept.value[0]),
    )
    const mark = createDerived(() =>
      props.kind === undefined
        ? 'artifact'
        : ({ code: 'terminal', document: 'document', data: 'table', preview: 'browser' } as const)[
            props.kind
          ],
    )
    const choices = createDerived(() =>
      (viewsKept.value ?? []).map((entry) => ({ value: entry.id, label: entry.label })),
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        overflowing.value = body.value !== null && body.value.scrollHeight > body.value.clientHeight
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [body.value, body.value?.firstElementChild])
        if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    watchEffect(
      createMemo(() => shown.value?.id),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'ArtifactPane',
        element: () => pane.value,
        state: () => ({
          view: shown.value?.id ?? null,
          views: (viewsKept.value ?? []).map((entry) => ({ id: entry.id, label: entry.label })),
          streaming: props.streaming,
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              value !== shown.value?.id && ((mirror.value = value), props.onViewChange?.(value)),
          },
          close: () =>
            (() => {
              if (!(props.onClose !== undefined)) throw new Error('The pane has no close control.')
              props.onClose?.()
            })(),
        },
        withholds: () => [switcher.value, closer.value],
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <section
        class={styles.pane}
        aria-labelledby={titleId.value}
        data-kind={props.kind}
        data-state={props.streaming ? 'streaming' : undefined}
        aria-busy={props.streaming ? true : undefined}
        data-member="artifact-pane"
        ref={pane.attach}
      >
        <header class={styles.header}>
          <span class={styles.mark}>
            {props.streaming ? (
              <Spinner size="sm" label={`${props.title}: still being written`} />
            ) : (
              <Icon name={mark.value} size="sm" />
            )}
          </span>
          <div class={styles.heading}>
            <h2 class={styles.title} id={titleId.value}>
              {props.title}
            </h2>
            {props.meta !== undefined ? <p class={styles.meta}>{props.meta}</p> : null}
          </div>
          {switching.value ? (
            <div class={styles.views} ref={switcher.attach}>
              <SegmentedControl
                size="sm"
                label={props.viewsLabel}
                options={choices.value}
                value={current.value}
                onChange={($event) => ((mirror.value = $event), props.onViewChange?.($event))}
              />
            </div>
          ) : null}
          {actionsSlot.filled() ? <div class={styles.actions}>{actionsSlot()}</div> : null}
          {props.onClose !== undefined ? (
            <div class={styles.close} ref={closer.attach}>
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="close"
                label={props.closeLabel}
                onClick={() => props.onClose?.()}
              />
            </div>
          ) : null}
        </header>
        <div
          class={styles.body}
          data-view={shown.value?.id}
          tabindex={overflowing.value ? 0 : undefined}
          role={overflowing.value ? 'group' : undefined}
          aria-labelledby={overflowing.value ? titleId.value : undefined}
          ref={body.attach}
        >
          <div class={styles.content}>
            {shown.value === undefined
              ? props.children
              : typeof shown.value.content === 'string'
                ? shown.value.content
                : shown.value.content}
          </div>
        </div>
      </section>
    )
  })
}
